-- SHALOM | Paso 3: Funciones de descubrimiento y busqueda avanzada
-- Solo para Supabase de SHALOM (ehpvsasyzlrlypjjpzuk).
-- No ejecutar en el proyecto Juntos Hacia Dios.
-- No copia ni elimina cantos, artistas ni usuarios.
-- Si aparece un error, detente y comparte el mensaje antes de seguir.
BEGIN;
CREATE OR REPLACE FUNCTION public.jhd_artist_discovery(p_artist_id uuid, p_limit integer DEFAULT 5)
 RETURNS TABLE(relation_kind text, artist_id uuid, artist_name text, artist_slug text, artist_type text, artist_bio text, artist_description text, shared_songs integer, shared_categories integer, same_type boolean, score integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                        with settings as (
                                            select greatest(1, least(coalesce(p_limit, 5), 12)) as max_items
                                              ),
                                                current_artist as (
                                                    select id, artist_type
                                                        from public.artists
                                                            where id = p_artist_id
                                                              ),
                                                                own_songs as (
                                                                    select distinct sa.song_id
                                                                        from public.song_artists sa
                                                                            where sa.artist_id = p_artist_id
                                                                              ),
                                                                                own_categories as (
                                                                                    select distinct sc.category_id
                                                                                        from public.song_categories sc
                                                                                            join own_songs os on os.song_id = sc.song_id
                                                                                              ),
                                                                                                collaborator_counts as (
                                                                                                    select
                                                                                                          sa.artist_id,
                                                                                                                count(distinct sa.song_id)::integer as shared_songs
                                                                                                                    from public.song_artists sa
                                                                                                                        join own_songs os on os.song_id = sa.song_id
                                                                                                                            where sa.artist_id <> p_artist_id
                                                                                                                                group by sa.artist_id
                                                                                                                                  ),
                                                                                                                                    category_counts as (
                                                                                                                                        select
                                                                                                                                              sa.artist_id,
                                                                                                                                                    count(distinct sc.category_id)::integer as shared_categories
                                                                                                                                                        from public.song_categories sc
                                                                                                                                                            join own_categories oc on oc.category_id = sc.category_id
                                                                                                                                                                join public.song_artists sa on sa.song_id = sc.song_id
                                                                                                                                                                    where sa.artist_id <> p_artist_id
                                                                                                                                                                        group by sa.artist_id
                                                                                                                                                                          ),
                                                                                                                                                                            same_type_artists as (
                                                                                                                                                                                select a.id as artist_id, true as same_type
                                                                                                                                                                                    from public.artists a
                                                                                                                                                                                        join current_artist ca on ca.artist_type is not null and a.artist_type = ca.artist_type
                                                                                                                                                                                            where a.id <> p_artist_id
                                                                                                                                                                                              ),
                                                                                                                                                                                                candidates as (
                                                                                                                                                                                                    select
                                                                                                                                                                                                          coalesce(cc.artist_id, cat.artist_id, sta.artist_id) as artist_id,
                                                                                                                                                                                                                coalesce(cc.shared_songs, 0) as shared_songs,
                                                                                                                                                                                                                      coalesce(cat.shared_categories, 0) as shared_categories,
                                                                                                                                                                                                                            coalesce(sta.same_type, false) as same_type
                                                                                                                                                                                                                                from collaborator_counts cc
                                                                                                                                                                                                                                    full join category_counts cat on cat.artist_id = cc.artist_id
                                                                                                                                                                                                                                        full join same_type_artists sta on sta.artist_id = coalesce(cc.artist_id, cat.artist_id)
                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                            joined as (
                                                                                                                                                                                                                                                select
                                                                                                                                                                                                                                                      a.id as artist_id,
                                                                                                                                                                                                                                                            a.name as artist_name,
                                                                                                                                                                                                                                                                  a.slug as artist_slug,
                                                                                                                                                                                                                                                                        a.artist_type,
                                                                                                                                                                                                                                                                              a.bio as artist_bio,
                                                                                                                                                                                                                                                                                    a.description as artist_description,
                                                                                                                                                                                                                                                                                          c.shared_songs,
                                                                                                                                                                                                                                                                                                c.shared_categories,
                                                                                                                                                                                                                                                                                                      c.same_type,
                                                                                                                                                                                                                                                                                                            (c.shared_songs * 100 + c.shared_categories * 10 + case when c.same_type then 1 else 0 end)::integer as score
                                                                                                                                                                                                                                                                                                                from candidates c
                                                                                                                                                                                                                                                                                                                    join public.artists a on a.id = c.artist_id
                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                        collaborators as (
                                                                                                                                                                                                                                                                                                                            select
                                                                                                                                                                                                                                                                                                                                  'collaborator'::text as relation_kind,
                                                                                                                                                                                                                                                                                                                                        artist_id, artist_name, artist_slug, artist_type, artist_bio, artist_description,
                                                                                                                                                                                                                                                                                                                                              shared_songs, shared_categories, same_type, score,
                                                                                                                                                                                                                                                                                                                                                    row_number() over (order by shared_songs desc, artist_name asc) as position
                                                                                                                                                                                                                                                                                                                                                        from joined
                                                                                                                                                                                                                                                                                                                                                            where shared_songs > 0
                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                related as (
                                                                                                                                                                                                                                                                                                                                                                    select
                                                                                                                                                                                                                                                                                                                                                                          'related'::text as relation_kind,
                                                                                                                                                                                                                                                                                                                                                                                artist_id, artist_name, artist_slug, artist_type, artist_bio, artist_description,
                                                                                                                                                                                                                                                                                                                                                                                      shared_songs, shared_categories, same_type, score,
                                                                                                                                                                                                                                                                                                                                                                                            row_number() over (order by score desc, artist_name asc) as position
                                                                                                                                                                                                                                                                                                                                                                                                from joined
                                                                                                                                                                                                                                                                                                                                                                                                    where shared_categories > 0 or same_type
                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                        select
                                                                                                                                                                                                                                                                                                                                                                                                            relation_kind,
                                                                                                                                                                                                                                                                                                                                                                                                                artist_id,
                                                                                                                                                                                                                                                                                                                                                                                                                    artist_name,
                                                                                                                                                                                                                                                                                                                                                                                                                        artist_slug,
                                                                                                                                                                                                                                                                                                                                                                                                                            artist_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                artist_bio,
                                                                                                                                                                                                                                                                                                                                                                                                                                    artist_description,
                                                                                                                                                                                                                                                                                                                                                                                                                                        shared_songs,
                                                                                                                                                                                                                                                                                                                                                                                                                                            shared_categories,
                                                                                                                                                                                                                                                                                                                                                                                                                                                same_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                    score
                                                                                                                                                                                                                                                                                                                                                                                                                                                      from collaborators, settings
                                                                                                                                                                                                                                                                                                                                                                                                                                                        where collaborators.position <= settings.max_items

                                                                                                                                                                                                                                                                                                                                                                                                                                                          union all

                                                                                                                                                                                                                                                                                                                                                                                                                                                            select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                relation_kind,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    artist_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        artist_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            artist_slug,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                artist_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    artist_bio,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        artist_description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            shared_songs,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shared_categories,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    same_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        score
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          from related, settings
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            where related.position <= settings.max_items;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $function$;
REVOKE EXECUTE ON FUNCTION public.jhd_artist_discovery(p_artist_id uuid, p_limit integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.jhd_artist_discovery(p_artist_id uuid, p_limit integer) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.search_songs_catalog(p_query text DEFAULT NULL::text, p_song_type text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_album_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, title text, slug text, tone text, song_type text, difficulty text, artists jsonb, categories jsonb, albums jsonb, total_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
                                                    with recursive category_tree(id) as (
                                                        select c.id
                                                            from public.categories c
                                                                where p_category_id is not null
                                                                      and c.id = p_category_id

                                                                          union

                                                                              select child.id
                                                                                  from public.categories child
                                                                                      join category_tree parent on child.parent_id = parent.id
                                                                                        ),
                                                                                          filtered as (
                                                                                              select
                                                                                                    s.id,
                                                                                                          s.title,
                                                                                                                s.slug,
                                                                                                                      s.tone,
                                                                                                                            s.song_type,
                                                                                                                                  s.difficulty,
                                                                                                                                        coalesce((
                                                                                                                                                select jsonb_agg(
                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                      'id', a.id,
                                                                                                                                                                                  'name', a.name,
                                                                                                                                                                                              'artist_type', a.artist_type
                                                                                                                                                                                                        )
                                                                                                                                                                                                                  order by lower(a.name)
                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                  from public.song_artists sa
                                                                                                                                                                                                                                          join public.artists a on a.id = sa.artist_id
                                                                                                                                                                                                                                                  where sa.song_id = s.id
                                                                                                                                                                                                                                                        ), '[]'::jsonb) as artists,
                                                                                                                                                                                                                                                              coalesce((
                                                                                                                                                                                                                                                                      select jsonb_agg(
                                                                                                                                                                                                                                                                                jsonb_build_object(
                                                                                                                                                                                                                                                                                            'id', c.id,
                                                                                                                                                                                                                                                                                                        'name', c.name,
                                                                                                                                                                                                                                                                                                                    'song_type', c.song_type,
                                                                                                                                                                                                                                                                                                                                'slug', c.slug
                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                    order by lower(c.name)
                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                    from public.song_categories sc
                                                                                                                                                                                                                                                                                                                                                                            join public.categories c on c.id = sc.category_id
                                                                                                                                                                                                                                                                                                                                                                                    where sc.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                          ), '[]'::jsonb) as categories,
                                                                                                                                                                                                                                                                                                                                                                                                coalesce((
                                                                                                                                                                                                                                                                                                                                                                                                        select jsonb_agg(
                                                                                                                                                                                                                                                                                                                                                                                                                  jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                              'id', al.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                          'title', al.title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                      'slug', al.slug
                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          order by lower(al.title)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          from public.album_songs als
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  join public.albums al on al.id = als.album_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where als.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ), '[]'::jsonb) as albums
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    from public.songs s
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      nullif(btrim(coalesce(p_song_type, '')), '') is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or lower(coalesce(s.song_type, '')) = lower(btrim(p_song_type))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_category_id is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          or exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from public.song_categories sc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where sc.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    and sc.category_id in (select id from category_tree)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        and (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_album_id is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        or exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            from public.album_songs als
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where als.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  and als.album_id = p_album_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      and (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              nullif(btrim(coalesce(p_query, '')), '') is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      or coalesce(s.title, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or coalesce(s.tone, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      or coalesce(s.difficulty, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or coalesce(s.song_type, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      or exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          from public.song_artists sa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    join public.artists a on a.id = sa.artist_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              where sa.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and coalesce(a.name, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          or exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from public.song_categories sc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        join public.categories c on c.id = sc.category_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where sc.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              and coalesce(c.name, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or exists (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        select 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from public.album_songs als
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            join public.albums al on al.id = als.album_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where als.song_id = s.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  and coalesce(al.title, '') ilike '%' || btrim(p_query) || '%'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        f.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            f.title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                f.slug,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    f.tone,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        f.song_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            f.difficulty,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                f.artists,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    f.categories,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        f.albums,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            count(*) over () as total_count
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from filtered f
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                order by lower(f.title), f.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  limit least(greatest(coalesce(p_limit, 24), 1), 100)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    offset greatest(coalesce(p_offset, 0), 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $function$;
REVOKE EXECUTE ON FUNCTION public.search_songs_catalog(p_query text, p_song_type text, p_category_id uuid, p_album_id uuid, p_limit integer, p_offset integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.search_songs_catalog(p_query text, p_song_type text, p_category_id uuid, p_album_id uuid, p_limit integer, p_offset integer) TO anon, authenticated;
COMMIT;
